#!/usr/bin/env python3
"""CLI interface for task-tracker-cli."""

import argparse
import csv
import json
import re
import sys
from datetime import datetime, timezone

from task_tracker_cli import categorizer, storage


def validate_task(task: str) -> tuple[bool, str]:
    if not re.match(r'^[a-zA-Z0-9 -]{1,50}$', task):
        return False, (
            "Task name must be 1-50 characters, "
            "containing only alphanumeric characters, spaces, and hyphens."
        )
    return True, ""


def cmd_start(args: argparse.Namespace) -> int:
    valid, msg = validate_task(args.task)
    if not valid:
        print(f"Error: {msg}", file=sys.stderr)
        return 2

    state = {
        "task": args.task,
        "start": datetime.now(timezone.utc).isoformat(),
    }
    storage.save_state(state)
    print(f"Started tracking: {args.task}")
    return 0


def cmd_stop(args: argparse.Namespace) -> int:
    active = storage.get_active_session()
    if active is None:
        print("No active session to stop.", file=sys.stderr)
        return 1

    end = datetime.now(timezone.utc)
    start = datetime.fromisoformat(active["start"])
    duration = (end - start).total_seconds()

    session = {
        "id": len(storage.load_sessions()) + 1,
        "task": active["task"],
        "category": categorizer.categorize(active["task"]),
        "duration": round(duration, 2),
        "start": active["start"],
        "end": end.isoformat(),
    }

    storage.append_session(session)
    storage.clear_active_session()
    print(f"Stopped tracking: {active['task']} ({duration:.2f}s)")
    return 0


def cmd_list(args: argparse.Namespace) -> int:
    sessions = storage.load_sessions()
    if not sessions:
        return 0

    sorted_sessions = sorted(sessions, key=lambda s: s["start"])

    headers = ["ID", "Task", "Category", "Duration", "Start", "End"]
    key_map = {"ID": "id", "Task": "task", "Category": "category", "Duration": "duration", "Start": "start", "End": "end"}
    rows = []
    for s in sorted_sessions:
        rows.append({
            "id": f"{s['id']:04d}",
            "task": s["task"],
            "category": s["category"],
            "duration": f"{s['duration']:.2f}",
            "start": s["start"],
            "end": s["end"],
        })

    col_widths = [len(h) for h in headers]
    for row in rows:
        for j, h in enumerate(headers):
            col_widths[j] = max(col_widths[j], len(row[key_map[h]]))

    def fmt(row):
        return (
            " | ".join(f"{row[key_map[h]]:<{w}}" for h, w in zip(headers, col_widths))
            .rstrip()
        )

    def fmt_header():
        return (
            " | ".join(f"{h:<{w}}" for h, w in zip(headers, col_widths))
            .rstrip()
        )

    sep = "-+-".join("-" * w for w in col_widths)

    lines = [fmt_header(), sep]
    for row in rows:
        lines.append(fmt(row))

    print("\n".join(lines))
    return 0


def cmd_export(args: argparse.Namespace) -> int:
    sessions = storage.load_sessions()
    fmt_type = args.format

    if fmt_type == "json":
        output = []
        for i, s in enumerate(sessions, start=1):
            output.append({
                "id": i,
                "task": s["task"],
                "category": s["category"],
                "duration": s["duration"],
                "start": s["start"],
                "end": s["end"],
            })
        json.dump(output, sys.stdout, indent=2)
        print()
    elif fmt_type == "csv":
        writer = csv.writer(sys.stdout, lineterminator="\n")
        writer.writerow(["id", "task", "category", "duration", "start", "end"])
        for i, s in enumerate(sessions, start=1):
            writer.writerow([i, s["task"], s["category"], s["duration"], s["start"], s["end"]])

    return 0


def main() -> int:
    parser = argparse.ArgumentParser(
        prog="task-tracker",
        description="Track engineering tasks",
    )
    subparsers = parser.add_subparsers(dest="command")

    start_p = subparsers.add_parser("start", help="Start tracking a task")
    start_p.add_argument("task", help="Task name")

    subparsers.add_parser("stop", help="Stop tracking current task")
    subparsers.add_parser("list", help="List all tracked sessions")

    export_p = subparsers.add_parser("export", help="Export sessions")
    export_p.add_argument(
        "--format", choices=["json", "csv"], required=True, help="Output format"
    )

    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        return 2

    storage.get_data_dir()

    commands = {
        "start": cmd_start,
        "stop": cmd_stop,
        "list": cmd_list,
        "export": cmd_export,
    }

    return commands[args.command](args)


if __name__ == "__main__":
    sys.exit(main())

def categorize(task: str) -> str:
    lower = task.lower()
    if any(kw in lower for kw in ['code', 'dev', 'bug', 'fix', 'refactor']):
        return 'engineering'
    if any(kw in lower for kw in ['meeting', 'sync', 'call', 'review']):
        return 'communication'
    return 'general'

"""JSON file-backed storage for task-tracker-cli."""

import json
import os
from pathlib import Path
from tempfile import mkstemp


DATA_DIR = Path.home() / ".task-tracker"
SESSIONS_FILE = DATA_DIR / "sessions.json"
STATE_FILE = DATA_DIR / "state.json"


def get_data_dir() -> Path:
    """Return the data directory path, creating it if necessary."""
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    return DATA_DIR


def _atomic_write(path: Path, data: str) -> None:
    """Write *data* to *path* atomically via temp file + rename."""
    fd, tmp_path = mkstemp(dir=path.parent)
    try:
        with os.fdopen(fd, "w") as f:
            f.write(data)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def load_sessions() -> list:
    """Load the sessions list from disk."""
    if not SESSIONS_FILE.exists():
        return []
    with open(SESSIONS_FILE, "r") as f:
        return json.load(f)


def save_sessions(sessions: list) -> None:
    """Atomically write the sessions list to disk."""
    _atomic_write(SESSIONS_FILE, json.dumps(sessions, indent=2))


def append_session(session: dict) -> None:
    """Append a session dict to the sessions list."""
    sessions = load_sessions()
    sessions.append(session)
    save_sessions(sessions)


def load_state() -> dict | None:
    """Load the active session state, or None if no active session."""
    if not STATE_FILE.exists():
        return None
    with open(STATE_FILE, "r") as f:
        data = json.load(f)
    return data if data is not None else None


def save_state(state: dict | None) -> None:
    """Atomically write the active session state (or null)."""
    _atomic_write(STATE_FILE, json.dumps(state, indent=2))


def get_active_session() -> dict | None:
    """Return the active session state, or None."""
    return load_state()


def clear_active_session() -> None:
    """Clear the active session state."""
    save_state(None)
